      "html": "        <section class=\"section-7__banner\" style=\"--d1:0.1; --d2:0.7; --d3:0.3; --d4:0.5; --d5:0.2;\">\n            <img class=\"section-7__falling-item\" loading=\"lazy\" width=\"200\" height=\"200\" aria-hidden=\"true\"\n                src=\"https://static1.efacil.com.br/wcsstore//AuroraStorefrontAssetStore/PDP/EQUIPE_QUALIDADE_CONTEUDO/logo-efacil.png\"\n                alt=\"\">\n            <img class=\"section-7__falling-item\" loading=\"lazy\" width=\"200\" height=\"200\" aria-hidden=\"true\"\n                src=\"https://static1.efacil.com.br/wcsstore//AuroraStorefrontAssetStore/PDP/EQUIPE_QUALIDADE_CONTEUDO/logo-efacil.png\"\n                alt=\"\">\n            <img class=\"section-7__falling-item\" loading=\"lazy\" width=\"200\" height=\"200\" aria-hidden=\"true\"\n                src=\"https://static1.efacil.com.br/wcsstore//AuroraStorefrontAssetStore/PDP/EQUIPE_QUALIDADE_CONTEUDO/logo-efacil.png\"\n                alt=\"\">\n            <img class=\"section-7__falling-item\" loading=\"lazy\" width=\"200\" height=\"200\" aria-hidden=\"true\"\n                src=\"https://static1.efacil.com.br/wcsstore//AuroraStorefrontAssetStore/PDP/EQUIPE_QUALIDADE_CONTEUDO/logo-efacil.png\"\n                alt=\"\">\n            <img class=\"section-7__falling-item\" loading=\"lazy\" width=\"200\" height=\"200\" aria-hidden=\"true\"\n                src=\"https://static1.efacil.com.br/wcsstore//AuroraStorefrontAssetStore/PDP/EQUIPE_QUALIDADE_CONTEUDO/logo-efacil.png\"\n                alt=\"\">\n            <img class=\"section-7__banner-image\" loading=\"lazy\" width=\"1600\" height=\"865\"\n                src=\"https://static1.efacil.com.br/wcsstore//AuroraStorefrontAssetStore/PDP/EQUIPE_QUALIDADE_CONTEUDO/sessao32.jpg\"\n                alt=\"Produto em destaque — qualidade, praticidade e estilo no dia a dia\">\n            <div class=\"section-7__grouptext-overlay bottom\">\n                <p style=\"color: #ffffff;\">Isso é uma descrição. Isso é uma descrição.</p>\n                <h2 style=\"color: #ffffff;\"><strong>SUB-TÍTULO</strong></h2>\n                <p style=\"color: #ffffff;\">Isso é uma descrição. Isso é uma descrição. Isso é uma descrição. Isso é\n                    umadescrição.\n                </p>\n            </div>\n        </section>",
      "css": "<style>\n  :root {\n    --fall-duration: 5s;\n    --fall-delay-range: 4s;\n  }\n\n  .section-7__wrapper {\n    width: 100%;\n    margin-inline: auto;\n  }\n\n  .section-7__banner {\n    position: relative;\n    width: 100%;\n    overflow: hidden;\n    margin: -1px;\n  }\n\n  .section-7__banner-image {\n    width: 100%;\n    height: auto;\n    display: block;\n  }\n\n  .section-7__grouptext-overlay {\n    position: absolute;\n    max-width: 40%;\n    width: 90%;\n    line-height: 1.5;\n    text-align: center;\n    font-family: sans-serif\n  }\n\n  .section-7__grouptext-overlay.top {\n    top: 3%;\n    left: 50%;\n    transform: translateX(-50%);\n  }\n\n  .section-7__grouptext-overlay.bottom {\n    top: 84%;\n    left: 50%;\n    transform: translateX(-50%);\n  }\n\n  .section-7__grouptext-overlay.left {\n    top: 50%;\n    left: 25%;\n    transform: translate(-50%, -50%);\n    max-width: 41%;\n  }\n\n  .section-7__grouptext-overlay.right {\n    top: 50%;\n    left: 75%;\n    transform: translate(-50%, -50%);\n    max-width: 42%;\n  }\n\n  .section-7__grouptext-overlay h2 {\n    font-size: 2vw;\n    font-weight: bold;\n    margin-bottom: 1.5px;\n    line-height: 120%;\n  }\n\n  .section-7__grouptext-overlay p {\n    font-size: 1.1vw;\n    margin: 0;\n    line-height: 120%;\n  }\n\n  @media (max-width: 960px) {\n    .section-7__grouptext-overlay h2 {\n      font-size: 2.1vw;\n    }\n\n    .section-7__grouptext-overlay p {\n      font-size: 1.5vw;\n    }\n  }\n\n  @media (max-width: 768px) {\n    .section-7__grouptext-overlay h2 {\n      font-size: 2.5vw;\n    }\n\n    .section-7__grouptext-overlay p {\n      font-size: 1.8vw;\n    }\n  }\n\n  @media (max-width: 500px) {\n    .section-7__grouptext-overlay h2 {\n      font-size: 3vw;\n    }\n\n    .section-7__grouptext-overlay p {\n      font-size: 2.3vw;\n    }\n  }\n\n  @media (max-width: 480px) {\n    .section-7__grouptext-overlay h2 {\n      font-size: 3vw;\n    }\n\n    .section-7__grouptext-overlay p {\n      font-size: 2.3vw;\n    }\n  }\n\n  @media (max-width: 1060px) {\n    .section-7__grouptext-overlay.top {\n      top: 3%;\n    }\n  }\n\n  @media (max-width: 960px) {\n    .section-7__grouptext-overlay.top {\n      top: 3%;\n    }\n  }\n\n  @media (max-width: 768px) {\n    .section-7__grouptext-overlay.top {\n      top: 3%;\n    }\n  }\n\n  @media (max-width: 500px) {\n    .section-7__grouptext-overlay.top {\n      top: 3%;\n    }\n  }\n\n  @media (max-width: 480px) {\n    .section-7__grouptext-overlay.top {\n      top: 3%;\n    }\n  }\n\n  @media (max-width: 1060px) {\n    .section-7__grouptext-overlay.bottom {\n      top: 81%;\n    }\n  }\n\n  @media (max-width: 960px) {\n    .section-7__grouptext-overlay.bottom {\n      top: 79%\n    }\n  }\n\n  @media (max-width: 480px) {\n    .section-7__grouptext-overlay.bottom {\n      top: 81%\n    }\n  }\n\n  @media (max-width: 768px) {\n    .section-7__grouptext-overlay.bottom {\n      top: 76%;\n    }\n  }\n\n  @media (max-width: 500px) {\n    .section-7__grouptext-overlay.bottom {\n      top: 67%;\n    }\n  }\n\n  @media (max-width: 480px) {\n\n    .section-7__grouptext-overlay.right {\n      top: 50%;\n      left: 73%;\n      transform: translate(-50%, -50%);\n    }\n  }\n\n  @media (max-width: 480px) {\n\n    .section-7__grouptext-overlay.left {\n      top: 50%;\n      left: 27%;\n      transform: translate(-50%, -50%);\n    }\n  }\n\n  .section-7__falling-item {\n    position: absolute;\n    top: -100px;\n    width: 8vw;\n    height: 8vw;\n    opacity: 0;\n    z-index: 10;\n    transform-origin: center;\n    animation: fall var(--fall-duration) infinite linear;\n    pointer-events: none;\n    user-select: none;\n  }\n\n  .section-7__falling-item:nth-child(1) {\n    left: 10%;\n    --start-rot: -30deg;\n    --end-rot: 360deg;\n    animation-delay: calc(var(--fall-delay-range) * var(--d1, 0.1));\n  }\n\n  .section-7__falling-item:nth-child(2) {\n    left: 30%;\n    --start-rot: 20deg;\n    --end-rot: 360deg;\n    animation-delay: calc(var(--fall-delay-range) * var(--d2, 0.7));\n  }\n\n  .section-7__falling-item:nth-child(3) {\n    left: 50%;\n    --start-rot: -45deg;\n    --end-rot: 360deg;\n    animation-delay: calc(var(--fall-delay-range) * var(--d3, 0.3));\n  }\n\n  .section-7__falling-item:nth-child(4) {\n    left: 70%;\n    --start-rot: 15deg;\n    --end-rot: 360deg;\n    animation-delay: calc(var(--fall-delay-range) * var(--d4, 0.5));\n  }\n\n  .section-7__falling-item:nth-child(5) {\n    left: 90%;\n    --start-rot: 45deg;\n    --end-rot: 360deg;\n    animation-delay: calc(var(--fall-delay-range) * var(--d5, 0.2));\n  }\n\n  @keyframes fall {\n    0% {\n      transform: translateY(-100px) rotate(var(--start-rot));\n      opacity: 1;\n    }\n\n    90% {\n      opacity: 1;\n    }\n\n    100% {\n      transform: translateY(110vh) rotate(var(--end-rot));\n      opacity: 0;\n    }\n  }\n</style>"
