      "html": "        <section id=\"faq-section\" aria-label=\"Perguntas frequentes\">\n            <div id=\"faq-section__header\">\n                <h2 id=\"faq-section__title\" id=\"faq-section-title\">Título Principal</h2>\n                <p id=\"faq-section__subtitle\">Sub-título</p>\n            </div>\n            <ul id=\"faq-section__list\">\n                <li id=\"faq-section__item\">\n                    <details id=\"faq-section__item\">\n                        <summary>\n                            <h3 id=\"faq-section__q-text\">Pergunta</h3>\n                            <span id=\"faq-section__icon\" aria-hidden=\"true\"></span>\n                        </summary>\n                        <div id=\"faq-section__a-inner\">\n                            <p id=\"faq-section__a-text\">Resposta</p>\n                        </div>\n                    </details>\n                </li>\n                <li id=\"faq-section__item\">\n                    <details id=\"faq-section__item\">\n                        <summary>\n                            <h3 id=\"faq-section__q-text\">Pergunta</h3>\n                            <span id=\"faq-section__icon\" aria-hidden=\"true\"></span>\n                        </summary>\n                        <div id=\"faq-section__a-inner\">\n                            <p id=\"faq-section__a-text\">Resposta</p>\n                        </div>\n                    </details>\n                </li>\n                <li id=\"faq-section__item\">\n                    <details id=\"faq-section__item\">\n                        <summary>\n                            <h3 id=\"faq-section__q-text\">Pergunta</h3>\n                            <span id=\"faq-section__icon\" aria-hidden=\"true\"></span>\n                        </summary>\n                        <div id=\"faq-section__a-inner\">\n                            <p id=\"faq-section__a-text\">Resposta</p>\n                        </div>\n                    </details>\n                </li>\n                <li id=\"faq-section__item\">\n                    <details id=\"faq-section__item\">\n                        <summary>\n                            <h3 id=\"faq-section__q-text\">Pergunta</h3>\n                            <span id=\"faq-section__icon\" aria-hidden=\"true\"></span>\n                        </summary>\n                        <div id=\"faq-section__a-inner\">\n                            <p id=\"faq-section__a-text\">Resposta</p>\n                        </div>\n                    </details>\n                </li>\n                <li id=\"faq-section__item\">\n                    <details id=\"faq-section__item\">\n                        <summary>\n                            <h3 id=\"faq-section__q-text\">Pergunta</h3>\n                            <span id=\"faq-section__icon\" aria-hidden=\"true\"></span>\n                        </summary>\n                        <div id=\"faq-section__a-inner\">\n                            <p id=\"faq-section__a-text\">Resposta</p>\n                        </div>\n                    </details>\n                </li>\n            </ul>\n        </section>",
      "css": "<style>\n    /*inicio-area-de-faq*/\n    #faq-section {\n        width: 100%;\n        padding: 2rem 16px;\n        box-sizing: border-box;\n        margin: 0 auto 25px;\n        padding-top: 0;\n        font-family: sans-serif;\n    }\n\n    #faq-section__header {\n        text-align: center;\n        margin: 1rem 0;\n    }\n\n    #faq-section__title {\n        font-size: clamp(1.5rem, 3vw, 2rem);\n        font-weight: bold;\n        color: #333;\n        margin: 0 0 12px;\n        line-height: 98%;\n    }\n\n    #faq-section__subtitle {\n        font-size: 1rem;\n        color: #666;\n        margin: 0;\n    }\n\n    #faq-section__list {\n        list-style: none;\n        margin: 0 auto;\n        padding: 0;\n        max-width: 60rem;\n        display: flex;\n        flex-direction: column;\n        gap: 8px;\n    }\n\n    #faq-section__item {\n        background: #fff;\n        border: 1px solid #e5e5e5;\n        border-radius: 12px;\n        overflow: hidden;\n    }\n\n    #faq-section__item summary {\n        display: flex;\n        align-items: center;\n        justify-content: space-between;\n        gap: 12px;\n        padding: 16px 20px;\n        cursor: pointer;\n        list-style: none;\n    }\n\n    #faq-section__item summary::-webkit-details-marker {\n        display: none;\n    }\n\n    #faq-section__item summary:hover {\n        background: #f9f9f9;\n    }\n\n    #faq-section__q-text {\n        font-size: 1rem;\n        font-weight: bold;\n        color: #333;\n        flex: 1;\n    }\n\n    #faq-section__q-text:hover {\n        color: #ea5b0c;\n    }\n\n    #faq-section__icon {\n        width: 20px;\n        height: 20px;\n        flex-shrink: 0;\n        position: relative;\n    }\n\n    #faq-section__icon::before,\n    #faq-section__icon::after {\n        content: '';\n        position: absolute;\n        background: #888;\n        border-radius: 2px;\n        transition: transform 0.25s ease, opacity 0.25s ease;\n    }\n\n    #faq-section__icon::before {\n        width: 12px;\n        height: 1.5px;\n        top: 9px;\n        left: 4px;\n    }\n\n    #faq-section__icon::after {\n        width: 1.5px;\n        height: 12px;\n        top: 4px;\n        left: 9px;\n    }\n\n    #faq-section__item[open] #faq-section__icon::after {\n        transform: rotate(90deg);\n        opacity: 0;\n    }\n\n    #faq-section__a-inner {\n        padding: 14px 20px 16px;\n        border-top: 1px solid #e5e5e5;\n    }\n\n    #faq-section__a-text {\n        font-size: 0.9rem;\n        color: #555;\n        line-height: 1.6;\n        margin: 0;\n    }\n\n    @media (max-width: 480px) {\n        #faq-section__q-text {\n            font-size: 0.9rem;\n        }\n    }\n    /*final-area-de-faq*/\n</style>"
