      "css": "  <style>\n    /* ── CONTAINER UNIVERSAL ── */\n    .section-14-container {\n      padding-top: 1.2rem;\n      padding-bottom: 1.2rem;\n    }\n\n    @media (min-width: 768px) {\n      .section-14-container {\n        max-width: 768px;\n        margin-inline: auto;\n      }\n    }\n\n    @media (min-width: 992px) {\n      .section-14-container {\n        max-width: 992px;\n      }\n    }\n\n    @media (min-width: 1200px) {\n      .section-14-container {\n        max-width: 1200px;\n      }\n    }\n\n    @media (min-width: 1536px) {\n      .section-14-container {\n        max-width: 1536px;\n      }\n    }\n\n    /* ── HEADER ── */\n    .section-14__header {\n      text-align: center;\n      margin-bottom: 40px;\n      padding-inline: 16px;\n    }\n\n    .section-14__title {\n      font-size: 2rem;\n      font-weight: 900;\n      color: #111;\n      margin: 0 0 16px;\n      line-height: 1.1;\n    }\n\n    .section-14__description {\n      font-size: 0.9375rem;\n      color: #555;\n      max-width: 700px;\n      margin-inline: auto;\n      line-height: 1.6;\n    }\n\n    /* ── BODY: mobile — coluna única ── */\n    .section-14__body {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      gap: 0;\n      padding-inline: 16px;\n    }\n\n    /* ── FEATURE BLOCK ── */\n    .section-14__feature {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      text-align: center;\n      padding: 15px 16px;\n    }\n\n    .section-14__icon {\n      width: 42px;\n      height: 42px;\n      border-radius: 12px;\n      margin-bottom: 12px;\n      padding: 10px;\n      background: #ff9100;\n      flex-shrink: 0;\n    }\n\n    .section-14__feature-title {\n      font-size: 1rem;\n      font-weight: 700;\n      color: #111;\n      margin: 0 0 8px;\n    }\n\n    .section-14__feature-text {\n      font-size: 0.875rem;\n      color: #666;\n      line-height: 1.5;\n      margin: 0;\n    }\n\n    /* ── IMAGEM CENTRAL ── */\n    .section-14__image-wrap {\n      width: 100%;\n    }\n\n    .section-14__image {\n      display: block;\n      width: 100%;\n      height: auto;\n      object-fit: cover;\n\n    }\n\n    /* ── COLUNA DE FEATURES ── */\n    .section-14__column {\n      display: flex;\n      flex-direction: column;\n      width: 100%;\n    }\n\n    /* ─────────────────────────────────────────────────\n      @media 768px — imagem central com features\n      sobrepostas nas bordas (layout imagem 2)\n  ───────────────────────────────────────────────── */\n    @media (min-width: 768px) {\n      .section-14__body {\n        position: relative;\n        flex-direction: row;\n        align-items: stretch;\n        padding-inline: 0;\n      }\n\n      .section-14__column {\n        width: auto;\n        flex: 0 0 220px;\n        justify-content: space-around;\n        z-index: 2;\n      }\n\n      .section-14__column--left {\n        align-items: flex-start;\n      }\n\n      .section-14__column--right {\n        align-items: flex-end;\n      }\n\n      .section-14__image-wrap {\n        flex: 1;\n        min-width: 0;\n        position: relative;\n      }\n\n      .section-14__image {\n        height: 100%;\n        border-radius: 16px;\n        object-fit: cover;\n      }\n\n      .section-14__feature {\n        align-items: flex-start;\n        text-align: left;\n        padding: 12px 16px;\n      }\n\n      .section-14__column--right .section-14__feature {\n        align-items: flex-end;\n        text-align: right;\n      }\n    }\n\n    @media (max-width: 767px) {\n      .section-14__image {\n        object-fit: cover;\n        width: 84%;\n        aspect-ratio: 9 / 6;\n        margin: auto;\n        border-radius: 20px;\n      }\n    }\n\n    @media (min-width: 992px) {\n      .section-14__image {\n        object-fit: cover;\n        width: 88%;\n        margin: auto;\n      }\n    }\n\n    /* ─────────────────────────────────────────────────\n      @media 1200px — 3 colunas separadas (layout imagem 3):\n      col-esq | imagem | col-dir, sem sobreposição\n  ───────────────────────────────────────────────── */\n    @media (min-width: 1200px) {\n      .section-14__body {\n        display: grid;\n        grid-template-columns: 1fr auto 1fr;\n        align-items: center;\n        gap: 48px;\n      }\n\n      .section-14__column {\n        width: 90%;\n        margin: auto;\n        gap: 58px;\n        justify-content: flex-start;\n      }\n\n      .section-14__column--left {\n        align-items: flex-start;\n      }\n\n      .section-14__column--right {\n        align-items: flex-end;\n      }\n\n      .section-14__image-wrap {\n        flex: unset;\n        width: 420px;\n      }\n\n      .section-14__image {\n        height: auto;\n        border-radius: 4px;\n        border-radius: 18px;\n      }\n\n      .section-14__feature {\n        padding: 0;\n      }\n    }\n  </style>"
